import { ref } from 'vue';

export type ChatModelOption = { label: string; value: string };

defineProps<{
  modelOptions: ChatModelOption[];
  usagePercent: number;
  usageUsedK: string;
  usageTotalK: string;
  sending: boolean;
  uploading: boolean;
  /** 已选择会话时可编辑、发送 */
  sessionActive: boolean;
}>();

const draft = defineModel<string>('draft', { required: true });
const activeModel = defineModel<string>('activeModel', { required: true });
const streamReplies = defineModel<boolean>('streamReplies', { default: true });
const useWS = defineModel<boolean>('useWS', { default: false });

const emit = defineEmits<{
  send: [];
  voice: [];
  fileChange: [event: Event];
  enterSend: [];
}>();

const fileInputRef = ref<HTMLInputElement | null>(null);

function onPickFile() {
  fileInputRef.value?.click();
}

function onFileChange(ev: Event) {
  emit('fileChange', ev);
}

function onEnterSend() {
  if (!draft.value.includes('\n') || draft.value.trim().length > 0) {
    emit('enterSend');
  }
}
